package com.novacommerce.inventory.domain;
import static org.assertj.core.api.Assertions.*; import com.novacommerce.inventory.api.dto.InventoryRequests.ReservationLine; import com.novacommerce.inventory.application.ReservationRequestHasher; import com.novacommerce.inventory.domain.inventory.*; import com.novacommerce.inventory.domain.reservation.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class InventoryDomainTests {private final Instant now=Instant.parse("2026-01-01T00:00:00Z");
 @Test void inventoryPreservesQuantityInvariants(){InventoryItem i=new InventoryItem(UUID.randomUUID(),10,now);assertThat(i.available()).isEqualTo(10);i.reserve(3,now);assertThat(i.getReserved()).isEqualTo(3);assertThat(i.available()).isEqualTo(7);assertThatThrownBy(()->i.reserve(8,now)).isInstanceOf(InsufficientStockException.class);i.release(3,now);assertThat(i.available()).isEqualTo(10);i.reserve(3,now);i.commit(3,now);assertThat(i.getOnHand()).isEqualTo(7);assertThat(i.getReserved()).isZero();assertThatThrownBy(()->i.adjust(-8,now)).isInstanceOf(StockAdjustmentConflictException.class);}
 @Test void reservationTransitionsAreIdempotentAndBounded(){InventoryReservation r=new InventoryReservation(UUID.randomUUID(),"key","hash",UUID.randomUUID(),now.plusSeconds(60),now,List.of(new ReservationItem(UUID.randomUUID(),1)));assertThat(r.release(now)).isTrue();assertThat(r.release(now)).isFalse();assertThatThrownBy(()->r.commit(now)).isInstanceOf(IllegalStateException.class);InventoryReservation c=new InventoryReservation(UUID.randomUUID(),"key2","hash",null,now.plusSeconds(60),now,List.of(new ReservationItem(UUID.randomUUID(),1)));assertThat(c.commit(now)).isTrue();assertThat(c.commit(now)).isFalse();}
 @Test void expirationOnlyTransitionsAnExpiredActiveReservationOnce(){InventoryReservation r=new InventoryReservation(UUID.randomUUID(),"expiry","hash",null,now.plusSeconds(60),now,List.of(new ReservationItem(UUID.randomUUID(),1)));assertThat(r.expire(now.plusSeconds(59))).isFalse();assertThat(r.expire(now.plusSeconds(61))).isTrue();assertThat(r.expire(now.plusSeconds(120))).isFalse();assertThat(r.getStatus()).isEqualTo(ReservationStatus.EXPIRED);}
 @Test void requestHashIsStableAcrossOrderAndSensitiveToQuantity(){UUID a=UUID.randomUUID(),b=UUID.randomUUID();ReservationRequestHasher h=new ReservationRequestHasher();assertThat(h.hash(List.of(new ReservationLine(a,2),new ReservationLine(b,1)))).isEqualTo(h.hash(List.of(new ReservationLine(b,1),new ReservationLine(a,2))));assertThat(h.hash(List.of(new ReservationLine(a,2)))).isNotEqualTo(h.hash(List.of(new ReservationLine(a,3))));}
}
